INSERT OR IGNORE INTO capability_ledger (capability, provenance, prerequisites, reliability, acquired_at, last_exercised_at, evidence) VALUES
 ('breach-doctor:second-path-watch', 'BREACH-DOCTOR-WATCH-1 (qnfo-cloud-ops 1.39.0 jobBreachDoctorWatch, migrations/2026-10-26-breach-doctor-watch.sql)',
  'qnfo-cloud-ops */10 tick, breach_diagnosis_events (migrations/2026-10-26-breach-doctor.sql), ops_config breach_doctor not off', 'unmeasured until the first chaos drill that reads the spof_alternate_probes row of the doctor tick component', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL,
  'a stalled breach doctor is measured (doctor_tick_age_min) and reported (one deduped issue with a d1-query contract) by a second worker, without a session');

-- Issue BREACH-DOCTOR-WATCH-1 (agent_issues 1000397) is narrowed, not closed, not superseded (doctrine section 6: status untouched, so issue_lifecycle logs nothing and v_issue_accounting still counts it open). Each statement is guarded by the
-- text it replaces, so a replay is a no-op. The description keeps the original design paragraph and replaces only the Definition of done line (no probe directive line is added, so the issue probe triggers stay quiet).
UPDATE agent_issues SET description = replace(description, 'Definition of done: a cloud_ops_events job-run row for job breach-doctor-watch is under 120 minutes old (the closing probe of this issue) and the spof_registry row names the tested alternate.', 'Scope narrowed 2026-10-26 by the BREACH-DOCTOR-WATCH-1 package (qnfo-cloud-ops 1.39.0, migrations/2026-10-26-breach-doctor-watch.sql). DELIVERED: the detect, measure and report half. jobBreachDoctorWatch writes doctor_tick_age_min, files one deduped issue titled BREACH-DOCTOR-1: doctor stalled (watch) when the newest tick is older than 30 minutes, and leaves a cloud_ops_events row of kind breach-doctor-watch on every run. That row is a heartbeat of its own kind and not a job-run row, so the earlier probe on job-run is replaced and a heartbeat does not close this issue. STILL OPEN: the acting half. When the tick is stale the watch runs the same validated per-issue playbooks (the S1 validators) and records every action in breach_diagnoses, and a drill reads that alternate and stamps alternate_tested_at on control_registry breach-doctor-switch (a control_alternate_probes row for the switch). The spof_registry stamp of the detect and report half comes from the drill probe in this file. The doer is unchanged. Definition of done (the closing probe of this issue): control_registry breach-doctor-switch has an alternate_tested_at and capability_ledger holds breach-doctor:second-path-playbooks, which the change that gives the watch its playbook branch writes in its own migration.')
WHERE id = (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-WATCH-1:%' ORDER BY id DESC LIMIT 1) AND status = 'open' AND instr(description, 'Definition of done: a cloud_ops_events job-run row for job breach-doctor-watch is under 120 minutes old (the closing probe of this issue) and the spof_registry row names the tested alternate.') > 0;

UPDATE remediation_contracts SET precondition = 'BREACH-DOCTOR-WATCH-1 (qnfo-cloud-ops 1.39.0) detects, measures and reports a stalled doctor tick but runs no playbook, so the diagnosis path still has one runner',
  action = 'a session adds the playbook branch to jobBreachDoctorWatch in qnfo-cloud-ops (the detect and report half is deployed) and the control_alternate_probes row for breach-doctor-switch, the stale-PR lane merges it and the canonical deploy ships it',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT alternate_tested_at FROM control_registry WHERE control = ''breach-doctor-switch'') IS NULL THEN ''control_registry breach-doctor-switch has no alternate_tested_at, so no drill has read an alternate that acts when the doctor tick stops'' WHEN NOT EXISTS (SELECT 1 FROM capability_ledger WHERE capability = ''breach-doctor:second-path-playbooks'') THEN ''capability_ledger has no breach-doctor:second-path-playbooks row, so the watch does not run the per-issue playbooks yet'' ELSE ''ok'' END AS observed'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-WATCH-1:%' ORDER BY id DESC LIMIT 1) AND instr(verify_probe, 'job-run') > 0
  AND (SELECT status FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-WATCH-1:%' ORDER BY id DESC LIMIT 1) = 'open';

-- DOCTRINE-1 (read and update control_registry): the switch row said the watch was a separate package, and it is built now; the alternate stays untested (alternate_tested_at is not written here).
UPDATE control_registry SET alternate_path = replace(alternate_path, 'the qnfo-cloud-ops watch (separate package) reads the same switch', 'qnfo-cloud-ops jobBreachDoctorWatch (BREACH-DOCTOR-WATCH-1, 1.39.0, built) reads the same switch and writes nothing while it is off, but runs no playbook yet, so this alternate stays untested until the acting half of issue BREACH-DOCTOR-WATCH-1 lands'),
  evidence = evidence || ' | BREACH-DOCTOR-WATCH-1 2026-10-26: alternate_path now names the built job (qnfo-cloud-ops 1.39.0 jobBreachDoctorWatch) and leaves the alternate untested until the acting half of issue BREACH-DOCTOR-WATCH-1 lands'
WHERE control = 'breach-doctor-switch' AND instr(alternate_path, 'the qnfo-cloud-ops watch (separate package) reads the same switch') > 0;

