INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session_01QpQv19uh1padRwZ3u1r766',
  'an issue that asks for two things is not closed on the cheaper one (OWNER-NO-LOOSE-ENDS-1, doctrine section 6), and a closing probe has to fail while the defect exists and be passable by the work that closes it',
  'BREACH-DOCTOR-WATCH-1-SCOPE: agent_issues 1000397 stays open and is narrowed to the acting half (the watch running the validated per-issue playbooks, and the alternate_tested_at stamp on control_registry breach-doctor-switch); its contract probe on cloud_ops_events kind job-run, which the delivered job never writes on a tick, is replaced by a probe on the unbuilt half; control_registry breach-doctor-switch alternate_path names the built job instead of a separate package',
  'qnfo-audit 2026-10-26T10:52Z (SELECT only): agent_issues 1000397 open, high, description asks for the playbook run and both stamps; its active contract issue-1000397 reads cloud_ops_events kind job-run for job breach-doctor-watch, and no such row exists; control_registry breach-doctor-switch has alternate_tested_at NULL and the text separate package; the job writes kind breach-doctor-watch only (qnfo-cloud-ops/breach-doctor-watch.test.mjs)',
